def type_name(value):
    if isinstance(value, bool):
        return 'boolean'
    if isinstance(value, int) and not isinstance(value, bool):
        return 'integer'
    if isinstance(value, float):
        return 'number'
    if isinstance(value, str):
        return 'string'
    if isinstance(value, list):
        return 'array'
    if isinstance(value, dict):
        return 'object'
    if value is None:
        return 'null'
    return type(value).__name__

class Validator:
    def __init__(self, schema):
        self.schema = schema
        self.errors = []

    def validate(self, instance, path=''):
        self.errors = []
        self._validate_schema(self.schema, instance, path)
        return self.errors

    def _validate_schema(self, schema, instance, path):
        # type
        if 'type' in schema:
            stype = schema['type']
            vtype = type_name(instance)
            ok = False
            if isinstance(stype, list):
                ok = vtype in stype
            else:
                ok = vtype == stype
            if not ok:
                self.errors.append(f'{format_value(instance)} is not of type "{stype}"')
                # Continue validating other constraints
        # numeric constraints
        if isinstance(instance, (int, float)) and 'minimum' in schema:
            try:
                minimum = schema['minimum']
                if instance < minimum:
                    self.errors.append(f'{format_value(instance)} is less than the minimum of {minimum}')
            except Exception:
                pass
        # object properties
        if isinstance(instance, dict) and 'properties' in schema:
            props = schema.get('properties', {})
            # required
            req = schema.get('required', [])
            for r in req:
                if r not in instance:
                    self.errors.append(f'\"{r}\" is a required property')
            # validate each property present with subschema
            for k, subs in props.items():
                if k in instance:
                    self._validate_schema(subs, instance[k], path + '/' + k)
        # arrays - not implemented deeply


def format_value(v):
    if isinstance(v, str):
        return f'"{v}"'
    return str(v)


def main(argv):
    if '--help' in argv or '-h' in argv:
        print_help_exact()
        return 0
    if '--version' in argv or '-v' in argv:
        sys.stdout.write('Version: ' + VERSION + '\n')
        return 0

