    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-i', '--instance', action='append')
    parser.add_argument('-d', '--draft')
    parser.add_argument('--assert-format', dest='assert_format', action='store_true')
    parser.add_argument('--no-assert-format', dest='assert_format', action='store_false')
    parser.add_argument('--output', choices=['text','flag','list','hierarchical'], default='text')
    parser.add_argument('--errors-only', action='store_true')
    parser.add_argument('--connect-timeout')
    parser.add_argument('--timeout')
    parser.add_argument('-k', '--insecure', action='store_true')
    parser.add_argument('--cacert')
    parser.add_argument('-v', '--version2', action='store_true')
    parser.add_argument('-h', '--help2', action='store_true')
    args, extras = parser.parse_known_args(argv[1:])

